/* Site public (W0, W1, W5–W15): landing, evenimente, obiective + ghid, hartă, planificator, oferte, comunitate, chat, contul meu, pagina firmei, login */

function periodChips(cur, act) { return [['today', 'Azi'], ['weekend', 'Weekend'], ['week', '7 zile'], ['all', 'Toate']].map(([k, l]) => `<button class="chip ${cur === k ? 'on' : ''}" data-act="${act}" data-arg="${k}">${l}</button>`).join(''); }
function pubEvents(p, f) { f = f || {}; let l = A.pubEvents().filter(e => !e.past && (p === 'all' ? true : A.inPeriod(e, p))); if (f.cats && f.cats.length) l = l.filter(e => f.cats.includes(e.cat)); if (f.price) l = l.filter(e => f.price === 'free' ? e.ticket === 'FREE' : f.price === 'app' ? e.ticket === 'IN_APP' : e.ticket === 'EXTERNAL'); if (f.org) l = l.filter(e => f.org === 'inst' ? e.org.type === 'INSTITUTION' : f.org === 'biz' ? e.org.type === 'BUSINESS' : e.org.type === 'CITY'); if (f.dist) l = l.filter(e => f.dist === 'city' ? e.dist < 10 : e.dist >= 10); if (f.hot) l = l.filter(A.isHot); if (f.q) { const n = f.q.toLowerCase(); l = l.filter(e => (e.title + e.venue).toLowerCase().includes(n)); } return l.sort((a, b) => f.sort === 'dist' ? a.dist - b.dist : (a.date + a.time).localeCompare(b.date + b.time)); }

/* ---------- W1 Landing ---------- */
route('/', () => {
  const p = UI.tmp.lp || 'today'; const f = UI.tmp.lf || ''; const list = pubEvents(p === 'today' && f ? 'week' : p, { hot: f === 'hot', price: f === 'free' ? 'free' : '', cats: f === 'family' ? ['FAMILY'] : f === 'concert' ? ['CONCERT'] : [] }).slice(0, 6);
  const acts = A.pubActions().slice(0, 2);
  return { title: 'Ce faci în Arad?', body: `<div class="split"><div>
      <div class="eyebrow">${A.TODAY_LABEL}</div><h1>Ce faci în Arad?</h1>
      <div class="row" style="margin-top:18px"><div class="search grow">${ms('search', 's')}<input placeholder="Caută evenimente, locuri, oferte…" data-bind="lq" data-enter="lsearch"></div><button class="iconbtn" style="width:46px;height:46px;border-radius:14px" data-go="/events">${ms('tune', 's')}</button></div>
      <div class="chips" style="margin:14px 0 18px">${periodChips(p, 'lp').slice(0, 0)}${[['today', 'Azi'], ['weekend', 'Weekend'], ['week', '7 zile']].map(([k, l]) => `<button class="chip ${p === k ? 'on' : ''}" data-act="lp" data-arg="${k}">${l}</button>`).join('')}<span style="width:1px;background:var(--line);margin:0 4px"></span>${[['hot', '🔥 Populare'], ['free', 'Gratuite'], ['family', 'Familie'], ['concert', 'Concerte']].map(([k, l]) => `<button class="chip ${f === k ? 'on' : ''}" data-act="lf" data-arg="${k}">${l}</button>`).join('')}</div>
      <div class="grid3">${list.map(e => evCardW(e)).join('') || empty('event_busy', 'Nimic în perioada asta', 'Încearcă alt filtru.')}</div>
      <div class="row" style="justify-content:space-between;margin:28px 0 12px"><h2>Locuri din Arad</h2><a class="chip sm" href="#/places">Toate obiectivele ${ms('arrow_forward', 'xs')}</a></div>
      <div class="grid4">${A.PLACES.slice(0, 4).map(pl => `<a class="evc" href="#/places/${pl.id}"><div class="img" style="${imgStyle(pl)};height:110px"><div class="tl"><span class="badge" style="background:#fff">${ms('headphones', 'xs')} ${pl.guide.length} puncte</span></div></div><div class="body"><b>${esc(pl.name)}</b><span>${esc(pl.type)} · ${pl.visitMin} min · ${A.km(pl.dist)}</span></div></a>`).join('')}</div>
    </div>
    <aside class="col" style="gap:14px">
      <a href="#/plan" class="card pad row" style="gap:14px;background:var(--ink);color:#fff;text-decoration:none;border:none">${ms('auto_awesome')}<div><b>În vizită? Planifică-ți ziua cu AI</b><div style="font-size:13px;opacity:.8;margin-top:3px">Cât timp ai, cum te deplasezi, ce îți place → program cu traseu și ghid audio</div></div></a>
      <div class="card" style="overflow:hidden"><div class="row" style="padding:10px 12px;gap:6px">${[['all', 'Toate'], ['ev', 'Evenimente'], ['offer', 'Oferte'], ['place', 'Obiective']].map(([k, l]) => `<button class="chip sm ${(UI.tmp.lk || 'all') === k ? 'on' : ''}" data-act="lk" data-arg="${k}">${l}</button>`).join('')}</div><div id="lmap" style="height:300px"></div><div style="padding:10px 12px" class="row"><span class="mut grow" style="font-size:12.5px">${mapItemsW().length} locuri pe hartă · azi</span><a class="btn sm" href="#/map">Deschide harta</a></div></div>
      <div class="card pad">${S.role === 'local' ? `<div class="ptscard" style="padding:14px"><div style="font-size:12.5px;opacity:.85">Punctele tale</div><div class="n" style="font-size:32px">${S.points}</div><div style="font-size:12.5px;opacity:.85">Locul 16 · 🔥 activ 2 luni la rând</div></div>` : `<div class="row" style="gap:10px">${ms('volunteer_activism')}<b>Comunitate</b></div><p class="sub">Acțiuni ale Primăriei cu puncte pentru localnici. Punctele se folosesc la firmele partenere.</p>`}
        <div style="margin-top:10px">${acts.map(a => `<a class="kv" href="#/community" style="text-decoration:none"><span class="badge pts">+${a.pts}</span><span class="grow"><b style="font-size:13.5px">${esc(a.title)}</b><div class="mut" style="font-size:12.5px">${A.dayLabel(a.date)} · ${a.time} · ${a.taken}/${a.spots}</div></span>${ms('chevron_right', 'xs')}</a>`).join('')}</div></div>
    </aside></div>`,
    after: () => { const map = mkMap('lmap', { zoom: 14, zoomControl: false }); if (!map) return; addPins(map, mapItemsW(UI.tmp.lk), it => go(it.href)); } };
});
ACT.lp = a => { UI.tmp.lp = a; UI.tmp.lf = ''; render(); };
ACT.lf = a => { UI.tmp.lf = UI.tmp.lf === a ? '' : a; render(); };
ACT.lk = a => { UI.tmp.lk = a; render(); };
ACT.lsearch = v => { UI.tmp.ef = Object.assign({}, UI.tmp.ef || {}, { q: v }); go('/events'); };
function mapItemsW(kind, period) { kind = kind || 'all'; period = period || 'today'; const out = []; const inCity = x => x.dist < 10;
  if (kind === 'all' || kind === 'ev') A.pubEvents().filter(e => A.inPeriod(e, period) && inCity(e)).forEach(e => out.push({ key: 'ev:' + e.id, pin: 'event', lat: e.lat, lng: e.lng, title: e.title, sub: `${A.whenLabel(e)} · ${e.venue}`, href: '/events/' + e.id, img: e.img, tone: e.tone, emoji: e.emoji, dist: e.dist, kindLabel: A.CATS[e.cat].l, badge: A.isHot(e) ? '🔥 ' + e.participants : e.ticket === 'FREE' ? 'Gratuit' : A.priceLabel(e) }));
  if (kind === 'all' || kind === 'place') A.PLACES.filter(inCity).forEach(p => out.push({ key: 'pl:' + p.id, pin: 'place', lat: p.lat, lng: p.lng, title: p.name, sub: p.type, href: '/places/' + p.id, tone: p.tone, emoji: '📍', dist: p.dist, kindLabel: 'Obiectiv', badge: `${p.guide.length} puncte de ghid` }));
  if (kind === 'all' || kind === 'offer') A.allBiz().filter(b => b.verified && inCity(b)).forEach(b => { const o = A.pubOffers().filter(x => x.biz === b.id); out.push({ key: 'bz:' + b.id, pin: 'offer', lat: b.lat, lng: b.lng, title: b.name, sub: `${b.cat} · ${o.length} oferte`, href: '/businesses/' + b.id, img: b.img, dist: b.dist, kindLabel: 'Firmă parteneră', badge: o[0] ? o[0].tag : '' }); });
  if (kind === 'all' || kind === 'act') A.pubActions().filter(a => A.haversine(A.CENTER, a) < 10).forEach(a => out.push({ key: 'ac:' + a.id, pin: 'action', lat: a.lat, lng: a.lng, title: a.title, sub: `${A.dayLabel(a.date)} · ${a.time}`, href: '/community', img: a.img, tone: a.tone, emoji: a.emoji, dist: A.haversine(A.CENTER, a), kindLabel: 'Acțiune', badge: '+' + a.pts + ' puncte' }));
  return out.sort((a, b) => a.dist - b.dist); }

/* ---------- W5 Evenimente ---------- */
route('/events', () => {
  const f = UI.tmp.ef = UI.tmp.ef || { p: 'all', cats: [], price: '', org: '', dist: '', sort: 'date', q: '' }; const list = pubEvents(f.p, f);
  const cb = (k, v, l) => { const on = k === 'cats' ? f.cats.includes(v) : f[k] === v; return `<label class="${on ? 'on' : ''}" data-act="ef" data-arg="${k}:${v}"><i>${on ? ms('check', 'xs') : ''}</i>${l}</label>`; };
  return { title: 'Evenimente în Arad', body: `<h1>Evenimente în Arad</h1><div class="sub">${list.length} evenimente${f.p === 'all' ? ' în următoarele 30 de zile' : ''} · reale (link spre organizator) și demo (bilete în aplicație)</div>
    <div class="split l" style="margin-top:20px"><aside class="fcol">
      <h4>Categorie</h4>${Object.entries(A.CATS).map(([k, c]) => cb('cats', k, c.l)).join('')}
      <h4>Preț</h4>${cb('price', 'free', 'Gratuite')}${cb('price', 'app', 'Cu bilete în aplicație')}${cb('price', 'ext', 'Pe site-ul organizatorului')}
      <h4>Organizator</h4>${cb('org', 'inst', 'Instituții')}${cb('org', 'biz', 'Firme locale')}${cb('org', 'city', 'Primăria Arad')}
      <h4>Distanță</h4>${cb('dist', 'city', 'În oraș')}${cb('dist', 'county', 'Județ (Miniș, Macea, Moneasa)')}
      <button class="btn sm sec" style="margin-top:16px" data-act="efclear">Șterge filtrele</button></aside>
    <div><div class="row" style="gap:10px;flex-wrap:wrap;margin-bottom:16px"><div class="search" style="width:300px">${ms('search', 's')}<input placeholder="Caută după titlu, loc, organizator…" data-bind="efq" data-enter="efsearch" value="${esc(f.q || '')}"></div>${periodChips(f.p, 'efp')}<span class="grow"></span><button class="chip sm" data-act="efsort">${ms('swap_vert', 'xs')} ${f.sort === 'date' ? 'După dată' : 'După distanță'}</button></div>
      <div class="grid3">${list.map(e => evCardW(e)).join('') || empty('event_busy', 'Niciun eveniment', 'Scoate un filtru sau alege altă perioadă.')}</div>
      <div class="row" style="justify-content:center;gap:6px;margin-top:22px"><button class="chip sm on">1</button><button class="chip sm">2</button><button class="chip sm">3</button><span class="mut" style="font-size:12.5px;margin-left:8px">9 pe pagină</span></div></div></div>` };
});
ACT.ef = a => { const [k, v] = a.split(':'); const f = UI.tmp.ef; if (k === 'cats') { const i = f.cats.indexOf(v); i >= 0 ? f.cats.splice(i, 1) : f.cats.push(v); } else f[k] = f[k] === v ? '' : v; render(); };
ACT.efp = a => { UI.tmp.ef.p = a; render(); }; ACT.efsort = () => { UI.tmp.ef.sort = UI.tmp.ef.sort === 'date' ? 'dist' : 'date'; render(); }; ACT.efclear = () => { UI.tmp.ef = null; render(); }; ACT.efsearch = v => { UI.tmp.ef.q = v; render(); };

/* ---------- W6 Detaliu eveniment + bilete ---------- */
route('/events/:id', ({ id }) => {
  const e = A.allEvents().find(x => x.id === id); if (!e) return { body: empty('error', 'Eveniment inexistent') };
  const o = UI.tmp.order = UI.tmp.order && UI.tmp.order.eventId === id ? UI.tmp.order : { eventId: id, ti: (e.times || []).findIndex(t => t.left > 0), adult: 1, child: e.priceChild ? 1 : 0 };
  const total = o.adult * (e.priceAdult || 0) + o.child * (e.priceChild || 0); const biz = e.org.bizId ? A.allBiz().find(b => b.id === e.org.bizId) : null; const place = e.placeId ? A.byId(A.PLACES, e.placeId) : null; const mine = S.tickets.find(t => t.eventId === id && !t.past);
  const box = e.ticket === 'IN_APP' ? `<div class="card pad ticketbox"><div class="row" style="justify-content:space-between"><b>Bilete în aplicație</b><span class="badge ink" style="font-size:11px">Doar în AradExperience</span></div>
      ${e.times ? `<div class="col" style="gap:6px;margin-top:12px">${e.times.map((t, i) => `<button class="kv" style="width:100%;text-align:left;${i === o.ti ? 'font-weight:600' : ''};${t.left === 0 ? 'opacity:.5' : ''}" ${t.left ? `data-act="pickTime" data-arg="${i}"` : ''}><span class="ms" style="font-size:18px">${i === o.ti ? 'radio_button_checked' : 'radio_button_unchecked'}</span><span class="grow">${A.dayLabel(t.d)} · ${t.t}</span><span class="mut" style="font-size:12px">${t.left === 0 ? 'epuizat' : t.left <= 5 ? `ultimele ${t.left}` : t.left + ' locuri'}</span></button>`).join('')}</div>` : `<div class="kv" style="margin-top:8px">${ms('schedule')}<span>${A.whenLabel(e)}</span></div>`}
      <div class="kv">${ms('location_on')}<span class="grow">${esc(e.venue)}</span><span class="mut" style="font-size:12px">${A.km(e.dist)}</span></div>${e.access ? `<div class="kv">${ms('accessible')}<span>Acces fără trepte</span></div>` : ''}
      <div class="kv" style="justify-content:space-between;margin-top:6px"><span>Adult · ${A.lei(e.priceAdult)}</span><span class="stepper"><button data-act="qty" data-arg="adult:-1">${ms('remove', 'xs')}</button><b>${o.adult}</b><button data-act="qty" data-arg="adult:1">${ms('add', 'xs')}</button></span></div>
      ${e.priceChild ? `<div class="kv" style="justify-content:space-between"><span>Copil (3–12 ani) · ${A.lei(e.priceChild)}</span><span class="stepper"><button data-act="qty" data-arg="child:-1">${ms('remove', 'xs')}</button><b>${o.child}</b><button data-act="qty" data-arg="child:1">${ms('add', 'xs')}</button></span></div>` : ''}
      <div class="row" style="justify-content:space-between;margin:12px 0 10px;font-size:16px"><b>Total</b><b>${A.lei(total)}</b></div>
      ${mine ? `<button class="btn lg" style="width:100%" data-act="showTicket" data-arg="${mine.code}">${ms('qr_code_2', 's')} Biletul meu · ${mine.code}</button>` : `<button class="btn lg" style="width:100%" data-act="buy" ${o.adult + o.child === 0 ? 'disabled' : ''}>${ms('lock', 's')} Continuă spre plată</button>`}
      <div class="mut" style="font-size:12px;margin-top:8px;text-align:center">Plată demonstrativă. Biletul apare în „Contul meu › Bilete” cu cod QR.</div></div>`
    : e.ticket === 'FREE' ? `<div class="card pad ticketbox"><b>${e.capacity ? 'Gratuit · cu înscriere' : 'Intrare liberă'}</b><div class="kv" style="margin-top:8px">${ms('schedule')}<span>${A.whenLabel(e)}</span></div><div class="kv">${ms('location_on')}<span>${esc(e.venue)}</span></div>${e.capacity ? `<div class="kv">${ms('group')}<span>${e.capacity - e.participants} locuri libere</span></div>` : ''}${e.capacity ? (mine ? `<button class="btn lg" style="width:100%;margin-top:10px" data-act="showTicket" data-arg="${mine.code}">${ms('qr_code_2', 's')} Înscrierea mea</button>` : `<button class="btn lg" style="width:100%;margin-top:10px" data-act="joinFree" data-arg="${id}">Înscrie-te · gratuit</button>`) : `<button class="btn lg sec" style="width:100%;margin-top:10px" data-act="cal">${ms('event_available', 's')} Adaugă în calendar</button>`}</div>`
      : `<div class="card pad ticketbox"><b>Bilete pe site-ul organizatorului</b><div class="sub">${esc(e.org.name)} · ${A.priceLabel(e)}</div><div class="kv" style="margin-top:8px">${ms('schedule')}<span>${A.whenLabel(e)}</span></div><div class="kv">${ms('location_on')}<span>${esc(e.venue)}</span></div><a class="btn lg" style="width:100%;margin-top:10px" href="${e.url || '#'}" target="_blank" rel="noopener">${ms('open_in_new', 's')} ${esc((e.url || '').replace('https://', '')) || 'Site organizator'}</a><div class="mut" style="font-size:12px;margin-top:8px;text-align:center">Biletele cumpărate acolo nu apar în aplicație.</div></div>`;
  return { title: e.title, body: `<div class="eyebrow" style="margin-bottom:10px"><a href="#/events" style="text-decoration:none">Evenimente</a> › ${A.CATS[e.cat].l}</div>
    <div class="split"><div>
      <div class="hero" style="${imgStyle(e)}"><div><div class="chips" style="margin-bottom:10px">${A.isHot(e) ? `<span class="badge hot">🔥 Popular · ${A.nf(e.participants || e.saves)} ${e.participants >= 50 ? 'participă' : 'au salvat'}</span>` : ''}${e.demo ? '<span class="badge" style="background:#fff">demo</span>' : ''}</div><h1>${esc(e.title)}</h1><div style="margin-top:6px;font-size:15px;opacity:.92">${esc(e.venue)} · ${A.whenLabel(e)}${e.dur ? ` · ${e.dur} min` : ''}</div></div>${e.credit ? `<span class="credit">${esc(e.credit)}</span>` : ''}</div>
      <div class="chips" style="margin:14px 0 22px"><button class="chip" data-act="saveW" data-arg="${id}">${ms(S.saved.includes(id) ? 'bookmark' : 'bookmark_border', 'xs')} ${S.saved.includes(id) ? 'Salvat' : 'Salvează'}</button><button class="chip" data-act="share">${ms('ios_share', 'xs')} Trimite</button><button class="chip" data-act="cal">${ms('event_available', 'xs')} Adaugă în calendar</button><a class="chip" href="#/map?to=ev:${id}" style="text-decoration:none">${ms('directions', 'xs')} Indicații</a></div>
      <h2>Despre eveniment</h2><p style="font-size:15px;color:var(--mut);line-height:1.55;margin:8px 0 0;max-width:680px">${esc(e.desc)}</p>
      <div class="card pad row" style="gap:14px;margin-top:18px">${biz ? `<div class="thumb" style="background-image:url('${biz.img}');width:48px;height:48px;border-radius:12px"></div><div class="grow"><b>Organizat de ${esc(biz.name)}</b><div class="sub" style="margin-top:2px">${esc(biz.cat)} · ★ ${biz.rating} (${biz.reviews}) ${biz.verified ? '· cont verificat' : ''}</div></div><a class="btn sm sec" href="#/businesses/${biz.id}">Pagina firmei</a>` : `<span class="avatar dark">${ms(e.org.type === 'CITY' ? 'account_balance' : 'domain', 's')}</span><div class="grow"><b>Organizat de ${esc(e.org.name)}</b>${e.url ? `<div class="sub" style="margin-top:2px">${esc(e.url.replace('https://', ''))}</div>` : ''}</div>`}</div>
      ${place ? `<a class="card pad row" style="gap:14px;margin-top:12px;text-decoration:none" href="#/places/${place.id}"><span class="avatar dark">${ms('headphones', 's')}</span><div class="grow"><b>Ghid virtual: ${esc(place.name)}</b><div class="sub" style="margin-top:2px">${place.guide.length} puncte · citit și audio · ${place.exteriorOnly ? 'se vizitează din exterior' : place.hours}</div></div>${ms('chevron_right')}</a>` : ''}
      ${e.reviews ? `<h2 style="margin-top:26px">Ce spun cei care au fost</h2><div class="card pad row" style="gap:18px;margin-top:10px;align-items:flex-start"><div><b style="font-size:36px;letter-spacing:-.03em">${e.rating || 4.5}</b><div class="stars">${stars(e.rating || 4.5)}</div><div class="mut" style="font-size:12px">${e.reviews.length} păreri · ediții anterioare</div></div><div class="grow">${e.reviews.map(r => `<div style="padding:8px 0;border-bottom:1px solid var(--line)"><b style="font-size:13.5px">${esc(r.who)}</b> <span class="stars" style="font-size:12px">${stars(r.stars)}</span><div class="mut" style="font-size:13.5px">„${esc(r.text)}”</div></div>`).join('')}</div></div>` : ''}
    </div><aside>${box}<div class="card" style="margin-top:14px;overflow:hidden"><div id="emap" style="height:220px"></div><div class="row" style="padding:10px 12px"><span class="mut grow" style="font-size:12.5px">${esc(e.addr)}</span><a class="btn sm sec" href="#/map?to=ev:${id}">Deschide harta</a></div></div></aside></div>`,
    after: () => { const map = mkMap('emap', { center: [e.lat, e.lng], zoom: 15, zoomControl: false }); if (map) L.marker([e.lat, e.lng], { icon: pinIcon('event') }).addTo(map); } };
});
ACT.pickTime = i => { UI.tmp.order.ti = +i; render(); };
ACT.qty = a => { const [k, d] = a.split(':'); const o = UI.tmp.order; o[k] = Math.max(0, Math.min(10, (o[k] || 0) + (+d))); render(); };
ACT.saveW = id => { const i = S.saved.indexOf(id); i >= 0 ? S.saved.splice(i, 1) : S.saved.push(id); save(); toast(i >= 0 ? 'Eliminat din Salvate.' : 'Salvat în Contul meu › Salvate.', 'bookmark'); render(); };
ACT.buy = () => {
  if (!S.user) { toast('Conectează-te ca să cumperi bilete.'); go('/login'); return; }
  const o = UI.tmp.order; const e = A.allEvents().find(x => x.id === o.eventId); const t = e.times ? e.times[o.ti] : { d: e.date, t: e.time };
  drawer(`<h2>Plată demonstrativă</h2><div class="sub">${esc(e.title)} · ${A.dayLabel(t.d)} · ${t.t}</div><div class="card pad" style="margin:16px 0">${[['Adult', o.adult, e.priceAdult], ['Copil', o.child, e.priceChild || 0]].filter(l => l[1]).map(l => `<div class="row" style="justify-content:space-between;font-size:14px;margin-bottom:6px"><span>${l[1]} × ${l[0]}</span><span>${A.lei(l[1] * l[2])}</span></div>`).join('')}<div class="row" style="justify-content:space-between;font-weight:700;border-top:1px solid var(--line);padding-top:8px"><span>Total</span><span>${A.lei(o.adult * e.priceAdult + o.child * (e.priceChild || 0))}</span></div></div>
    <div class="f"><label>E-mail pentru bilete</label><input class="in" value="${esc(S.user.email)}"></div><div class="f" style="margin-top:12px"><label>Plătești cu</label><div class="kv">${ms('credit_card')} Card salvat •••• 4821 <span class="grow"></span>${ms('radio_button_checked')}</div><div class="kv">${ms('add_card')} Card nou <span class="grow"></span>${ms('radio_button_unchecked')}</div></div>
    <button class="btn lg" style="width:100%;margin-top:18px" data-act="payNow">${ms('lock', 's')} Plătește ${A.lei(o.adult * e.priceAdult + o.child * (e.priceChild || 0))}</button><div class="mut" style="font-size:12px;margin-top:8px">Nu se procesează bani. Prin plată accepți condițiile organizatorului.</div>`);
};
ACT.payNow = () => { const o = UI.tmp.order; const e = A.allEvents().find(x => x.id === o.eventId); const t = e.times ? e.times[o.ti] : { d: e.date, t: e.time }; const lines = [['Adult', o.adult, e.priceAdult], ['Copil', o.child, e.priceChild || 0]].filter(l => l[1]); const code = A.genCode(`AX-T${o.eventId.replace('ev', '')}`); S.tickets.push({ code, eventId: o.eventId, date: t.d, time: t.t, lines, total: lines.reduce((s, l) => s + l[1] * l[2], 0), email: S.user.email }); if (t.left != null) t.left -= o.adult + o.child; save(); UI.tmp.order = null; ACT.showTicket(code); toast('Rezervarea e confirmată. Am trimis o copie pe e-mail.', 'check_circle'); render(); };
ACT.joinFree = id => { if (!S.user) { go('/login'); return; } const e = A.allEvents().find(x => x.id === id); const code = A.genCode(`AX-T${id.replace('ev', '')}`); S.tickets.push({ code, eventId: id, date: e.date, time: e.time, lines: [['Înscriere', 1, 0]], total: 0, email: S.user.email }); save(); ACT.showTicket(code); render(); };
ACT.showTicket = code => { const t = S.tickets.find(x => x.code === code); const e = A.allEvents().find(x => x.id === t.eventId); drawer(`<h2>${t.total ? 'Bilet' : 'Înscriere'}</h2><div class="sub">${esc(e.title)}<br>${A.dayLabel(t.date)} · ${t.time} · ${esc(e.venue)}</div><div class="card pad" style="margin:16px 0;text-align:center">${qrW(code, 200).replace('style="width:200px"', 'style="width:200px;margin:0 auto"')}<code style="font-size:14px;margin-top:10px;display:inline-block">${code}</code><div class="mut" style="font-size:12.5px;margin-top:6px">Arată codul la intrare. Funcționează și offline, în aplicație.</div></div>${t.lines.map(l => `<div class="row" style="justify-content:space-between;font-size:13.5px"><span>${l[1]} × ${l[0]}</span><span>${l[2] ? A.lei(l[1] * l[2]) : 'gratuit'}</span></div>`).join('')}<div class="row" style="gap:8px;margin-top:18px"><button class="btn sec" data-act="cal">${ms('event_available', 'xs')} Calendar</button><button class="btn sec" data-act="na">${ms('smartphone', 'xs')} Trimite pe telefon</button><a class="btn sec" href="#/account/tickets">Contul meu</a></div>`); };

/* ---------- W7 Obiective ---------- */
route('/places', () => {
  const f = UI.tmp.pf || 'all'; const list = A.PLACES.filter(p => f === 'all' || p.tags.includes(f));
  return { title: 'Obiective', body: `<h1>Obiective cu ghid virtual</h1><div class="sub">${A.PLACES.length} locuri din Arad și din județ, cu ghid scris și audio · date reale (program, tarife)</div>
    <div class="row" style="margin:18px 0 16px;flex-wrap:wrap"><div class="chips">${[['all', 'Toate'], ['istorie', 'Istorie'], ['muzee', 'Muzee'], ['natură', 'Natură'], ['crame', 'Crame & vin'], ['familie', 'Familie'], ['foto', 'Foto']].map(([k, l]) => `<button class="chip ${f === k ? 'on' : ''}" data-act="pf" data-arg="${k}">${l}</button>`).join('')}</div><span class="grow"></span><button class="chip" data-act="na">${ms('near_me', 'xs')} Lângă mine</button></div>
    <div class="split"><div class="grid2">${list.map(p => `<a class="evc" href="#/places/${p.id}"><div class="img" style="${imgStyle(p)};height:140px"><div class="tl"><span class="badge" style="background:#fff">${ms('headphones', 'xs')} ${p.guide.length} puncte · ${p.guide.reduce((s, g) => s + g.min, 0)} min</span>${p.exteriorOnly ? '<span class="badge ext" style="background:#fff">exterior</span>' : ''}</div></div><div class="body"><b>${esc(p.name)}</b><span>${esc(p.type)} · ${p.visitMin} min · ${A.km(p.dist)}</span></div></a>`).join('')}</div><aside><div class="map" id="pmap" style="height:620px;position:sticky;top:84px"></div></aside></div>`,
    after: () => { const map = mkMap('pmap', { zoom: 13 }); if (!map) return; addPins(map, list.filter(p => p.dist < 10).map(p => ({ key: p.id, pin: 'place', lat: p.lat, lng: p.lng, href: '/places/' + p.id })), it => go(it.href)); } };
});
ACT.pf = a => { UI.tmp.pf = a; render(); };

/* ---------- W8 Ghid virtual ---------- */
route('/places/:id', ({ id }) => {
  const p = A.byId(A.PLACES, id); if (!p) return { body: empty('error', 'Loc inexistent') }; const g = UI.guide = UI.guide && UI.guide.id === id ? UI.guide : { id, i: 0, playing: false, rate: 1 }; const evs = A.pubEvents().filter(e => e.placeId === id && !e.past).slice(0, 4);
  return { title: p.name, body: `<div class="eyebrow" style="margin-bottom:10px"><a href="#/places" style="text-decoration:none">Obiective</a> › ${esc(p.tags[0])}</div>
    <div class="split"><div>
      <div class="hero" style="${imgStyle(p)}"><div><h1>${esc(p.name)}</h1><div style="margin-top:6px;font-size:15px;opacity:.92">${esc(p.type)} · ${esc(p.hours)}${p.parking ? ' · Parcare: ' + esc(p.parking) : ''}</div></div>${p.credit ? `<span class="credit">${esc(p.credit)}</span>` : ''}</div>
      <div class="chips" style="margin:14px 0"><span class="badge info">${ms('headphones', 'xs')} Ghid virtual · ${p.guide.length} puncte · ~${p.guide.reduce((s, x) => s + x.min, 0)} min</span>${p.exteriorOnly ? '<span class="badge ext">Se vizitează doar din exterior</span>' : ''}<span class="badge">RO · EN · HU (planificat)</span></div>
      <div class="audio"><button class="play" data-act="gPlay">${ms(g.playing ? 'pause' : 'play_arrow', 'f')}</button><div class="grow"><b style="font-size:14px">${g.i + 1} · ${esc(p.guide[g.i].t)}</b><div class="ln"><i style="width:${g.playing ? 60 : 8}%"></i></div><span style="font-size:12px;opacity:.8">${g.playing ? 'se redă' : '0:00'} / ${p.guide[g.i].min}:${g.i % 2 ? '10' : '40'} · voce română (text-to-speech din browser)</span></div><button class="chip sm" style="background:transparent;color:#fff;border-color:rgba(255,255,255,.35)" data-act="gRate">${g.rate}×</button></div>
      <div style="margin-top:8px">${p.guide.map((x, i) => `<button class="gp ${i === g.i ? 'on' : ''}" style="width:100%;text-align:left" data-act="gPick" data-arg="${i}"><span class="n">${i + 1}</span><div class="grow"><div class="row" style="justify-content:space-between"><b>${esc(x.t)}</b><span class="mut" style="font-size:12.5px">${ms('play_circle', 'xs')} ${x.min} min</span></div><p ${i === g.i ? 'style="color:var(--ink)"' : ''}>${esc(x.text)}</p></div></button>`).join('')}</div>
      <p class="mut" style="font-size:12px;margin-top:14px">Texte scrise pentru citit cu voce tare; surse în docs/ARAD-DATA.md.</p>
    </div><aside class="col" style="gap:14px">
      <div class="card" style="overflow:hidden"><div style="padding:10px 12px;font-size:12.5px;color:var(--mut)">Punctele de ghid pe hartă</div><div id="gmap" style="height:220px"></div></div>
      <div class="card pad"><b>Informații</b><div class="kv" style="margin-top:6px">${ms('schedule')}<span>${esc(p.hours)}</span></div><div class="kv">${ms('timer')}<span>Vizită: ~${p.visitMin} min</span></div>${p.price ? `<div class="kv">${ms('payments')}<span>${esc(p.price)}</span></div>` : ''}${p.parking ? `<div class="kv">${ms('local_parking')}<span>${esc(p.parking)}</span></div>` : ''}<div class="kv">${ms('directions_walk')}<span>${A.km(p.dist)} de la Palatul Administrativ</span></div><div class="row" style="gap:8px;margin-top:12px"><a class="btn sm" href="#/plan">${ms('auto_awesome', 'xs')} Pune în program</a><a class="btn sm sec" href="#/map?to=pl:${id}">${ms('directions', 'xs')} Indicații</a></div></div>
      ${evs.length ? `<div class="card pad"><b>Evenimente aici</b>${evs.map(e => `<a class="kv" href="#/events/${e.id}" style="text-decoration:none">${ms('calendar_month')}<span class="grow">${esc(e.title)}</span><span class="mut" style="font-size:12px">${A.dayLabel(e.date)}, ${e.time}</span></a>`).join('')}</div>` : ''}
      <p class="mut" style="font-size:13px;line-height:1.5">${esc(p.desc)}</p></aside></div>`,
    after: () => { const map = mkMap('gmap', { center: [p.lat, p.lng], zoom: 16, zoomControl: false, me: false }); if (!map) return; p.guide.forEach((x, i) => L.marker([p.lat + (i % 3 - 1) * 0.0009, p.lng + (Math.floor(i / 3) - .5) * 0.0014], { icon: pinIcon('num', i + 1, i === g.i) }).addTo(map)); } };
});
function speakW(text, rate) { try { if (!window.speechSynthesis) return; speechSynthesis.cancel(); const u = new SpeechSynthesisUtterance(text); u.lang = 'ro-RO'; u.rate = rate || 1; u.onend = () => { if (UI.guide) { UI.guide.playing = false; render(); } }; speechSynthesis.speak(u); } catch (e) { } }
ACT.gPlay = () => { const g = UI.guide; const p = A.byId(A.PLACES, g.id); g.playing = !g.playing; if (g.playing) speakW(p.guide[g.i].t + '. ' + p.guide[g.i].text, g.rate); else { try { speechSynthesis.cancel(); } catch (e) { } } render(); };
ACT.gPick = i => { const g = UI.guide; g.i = +i; if (g.playing) speakW(A.byId(A.PLACES, g.id).guide[g.i].text, g.rate); render(); };
ACT.gRate = () => { const g = UI.guide; g.rate = g.rate === 1 ? 1.25 : g.rate === 1.25 ? 1.5 : 1; render(); };

/* ---------- W9 Hartă ---------- */
route('/map', (p, q) => {
  const m = UI.wmap = UI.wmap || { period: 'today', kind: 'all', sel: null, to: null }; if (q.to) { m.to = q.to; m.sel = q.to; m.kind = 'all'; }
  const items = mapItemsW(m.kind, m.period); const all = mapItemsW('all', 'all'); const sel = m.sel ? all.find(i => i.key === m.sel) : null;
  return { title: 'Hartă', body: `<div class="split lm"><aside class="card" style="overflow:hidden;height:calc(100vh - 150px);display:flex;flex-direction:column"><div style="padding:14px 14px 10px" class="col"><div class="search">${ms('search', 's')}<input placeholder="Caută pe hartă"></div><div class="chips" style="margin-top:10px">${periodChips(m.period, 'wmp')}</div><div class="chips" style="margin-top:8px">${[['all', 'Toate'], ['ev', 'Evenimente'], ['offer', 'Oferte'], ['place', 'Obiective'], ['act', 'Acțiuni']].map(([k, l]) => `<button class="chip sm ${m.kind === k ? 'on' : ''}" data-act="wmk" data-arg="${k}">${l}</button>`).join('')}</div><div class="mut" style="font-size:12.5px;margin-top:10px">${items.length} rezultate în zona hărții · sortate după distanță</div></div>
      <div style="overflow-y:auto;flex:1">${items.map(it => `<button class="row" style="gap:12px;padding:10px 14px;width:100%;border-top:1px solid var(--line);text-align:left;${m.sel === it.key ? 'background:var(--soft)' : ''}" data-act="wms" data-arg="${it.key}"><div class="thumb" style="${it.img ? `background-image:url('${it.img}')` : `background:${it.tone}`}">${it.img ? '' : (it.emoji || '')}</div><div class="grow"><b style="font-size:13.5px;display:block">${esc(it.title)}</b><span class="mut" style="font-size:12px">${esc(it.sub)} · ${A.km(it.dist)}</span>${m.sel === it.key ? `<div class="row" style="gap:6px;margin-top:8px"><button class="btn sm" data-act="wmr" data-arg="${it.key}">Arată traseul</button><a class="btn sm sec" href="#${it.href}">Deschide</a></div>` : ''}</div>${it.badge ? `<span class="badge" style="font-size:11px">${esc(it.badge)}</span>` : ''}</button>`).join('')}</div></aside>
    <div class="map" id="wmap" style="height:calc(100vh - 150px)"></div></div>${sel && m.to === sel.key ? `<div class="toast" style="bottom:60px">${ms('directions_walk')} Traseu pe jos: ${Math.max(1, Math.round(sel.dist / 5 * 60))} min · ${A.km(sel.dist)} <button class="chip sm" style="margin-left:8px" data-act="gmaps">Google Maps</button></div>` : ''}`,
    after: () => { const map = mkMap('wmap', { zoom: 14 }); if (!map) return; addPins(map, items, it => { m.sel = it.key; render(); }, m.sel); if (sel && m.to === sel.key) { L.polyline([[A.CENTER.lat, A.CENTER.lng], [sel.lat, sel.lng]], { color: '#111', weight: 4, dashArray: '2 8' }).addTo(map); map.fitBounds([[A.CENTER.lat, A.CENTER.lng], [sel.lat, sel.lng]], { padding: [60, 60] }); fetch(`https://routing.openstreetmap.de/routed-foot/route/v1/driving/${A.CENTER.lng},${A.CENTER.lat};${sel.lng},${sel.lat}?overview=full&geometries=geojson`).then(r => r.json()).then(j => { if (j.routes && UI.maps.includes(map)) L.polyline(j.routes[0].geometry.coordinates.map(c => [c[1], c[0]]), { color: '#1D5FD1', weight: 5 }).addTo(map); }).catch(() => { }); } else if (sel) map.setView([sel.lat, sel.lng], 16); } };
});
ACT.wmp = a => { UI.wmap.period = a; render(); }; ACT.wmk = a => { UI.wmap.kind = a; render(); }; ACT.wms = a => { UI.wmap.sel = UI.wmap.sel === a ? null : a; UI.wmap.to = null; render(); }; ACT.wmr = a => { UI.wmap.to = a; render(); };

/* ---------- W10 Planificator ---------- */
route('/plan', () => {
  const w = UI.plan = UI.plan || { time: 'half', day: '2026-11-07', transport: 'walk', interests: ['istorie', 'gastronomie'], text: '', result: null, loading: false };
  const chip = (k, v, l) => `<button class="chip ${k === 'interests' ? (w.interests.includes(v) ? 'on' : '') : (w[k] === v ? 'on' : '')}" data-act="pw" data-arg="${k}:${v}">${l}</button>`;
  const it = w.result; const stops = it ? it.stops.map(s => Object.assign({}, s, stopInfoW(s))) : [];
  return { title: 'Planifică-ți vizita', body: `<div style="display:grid;grid-template-columns:300px minmax(0,1fr) minmax(0,1fr);gap:22px;align-items:start">
    <aside><h2 style="font-size:24px">Planifică-ți vizita</h2><div class="sub">Program generat cu AI din obiective și evenimente reale.</div>
      <h4 class="eyebrow" style="margin:18px 0 8px;font-weight:600">Cât timp ai?</h4><div class="chips">${chip('time', '3h', '3 ore')}${chip('time', 'half', 'Jumătate de zi')}${chip('time', 'day', 'O zi')}${chip('time', '2d', '2 zile')}</div>
      <h4 class="eyebrow" style="margin:18px 0 8px;font-weight:600">Când?</h4><div class="chips">${chip('day', '2026-11-07', 'Sâm., 7 nov.')}${chip('day', '2026-11-08', 'Dum., 8 nov.')}<span class="chip">${ms('schedule', 'xs')} de la 10:00</span></div>
      <h4 class="eyebrow" style="margin:18px 0 8px;font-weight:600">Cum te deplasezi?</h4><div class="row" style="gap:8px">${[['walk', 'directions_walk', 'Pe jos'], ['car', 'directions_car', 'Mașină'], ['public', 'tram', 'Transport']].map(([k, ic, l]) => `<button class="card pad grow" style="padding:12px 8px;text-align:center;${w.transport === k ? 'border:2px solid var(--ink)' : ''}" data-act="pw" data-arg="transport:${k}">${ms(ic)}<div style="font-size:12.5px;font-weight:600;margin-top:4px">${l}</div></button>`).join('')}</div>
      <h4 class="eyebrow" style="margin:18px 0 8px;font-weight:600">Ce te interesează?</h4><div class="chips">${['istorie', 'crame & vin', 'muzee', 'natură', 'familie', 'gastronomie'].map(i => chip('interests', i, i[0].toUpperCase() + i.slice(1))).join('')}</div>
      <h4 class="eyebrow" style="margin:18px 0 8px;font-weight:600">Altceva?</h4><textarea class="in" placeholder="Vreau neapărat Cetatea și o cafea bună." data-bind="planText">${esc(w.text)}</textarea>
      <button class="btn lg" style="width:100%;margin-top:14px" data-act="pwGo" ${w.loading ? 'disabled' : ''}>${ms('auto_awesome', 's')} ${w.loading ? 'AradBot lucrează…' : 'Generează programul'}</button></aside>
    <section>${it ? `<div class="row" style="gap:10px"><h2>Programul tău</h2><span class="badge free">generat în 6 s</span></div><div class="sub">${esc(it.when)} · ${w.transport === 'walk' ? 'pe jos' : w.transport === 'car' ? 'cu mașina' : 'transport public'} · ${it.stops.length} opriri · 3,1 km</div>
        <div class="card pad" style="margin-top:14px;background:var(--soft);border:none;font-size:13.5px">${ms('auto_awesome', 'xs')} ${esc(it.summary)}</div>
        <div style="margin-top:14px">${stops.map((s, i) => `<div class="row" style="gap:14px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--line)"><div class="mut" style="width:44px;font-size:12.5px;line-height:1.3">${s.time}</div><span class="avatar dark" style="width:26px;height:26px;font-size:12px">${i + 1}</span><div class="thumb" style="${s.img ? `background-image:url('${s.img}')` : `background:${s.tone}`}">${s.img ? '' : (s.emoji || '')}</div><div class="grow"><b style="font-size:14px">${esc(s.title)}</b><div class="mut" style="font-size:12.5px">${s.dur}${s.guide ? ` · <span class="badge info" style="font-size:11px">${ms('headphones', 'xs')} ghid audio</span>` : ''}${s.tip ? ' · ' + esc(s.tip) : ''}</div>${s.walk ? `<div class="mut" style="font-size:12px;margin-top:4px">${ms('directions_walk', 'xs')} ${s.walk}${w.transport === 'car' && s.kind === 'place' ? ' · P: ' + esc((A.byId(A.PLACES, s.ref) || {}).parking || 'în zonă') : ''}</div>` : ''}</div><a class="btn sm sec" href="#${s.href}">${s.guide ? 'Ghid' : 'Detalii'}</a></div>`).join('')}</div>
        <div class="row" style="gap:8px;margin-top:16px"><button class="btn" data-act="toast" data-arg="Itinerar salvat. Link de partajare copiat.">${ms('bookmark', 'xs')} Salvează</button><button class="btn sec" data-act="toast" data-arg="Trimis în aplicație (Profil › Itinerariile tale).">${ms('smartphone', 'xs')} Trimite pe telefon</button><button class="btn sec" data-act="toast" data-arg="PDF generat.">${ms('picture_as_pdf', 'xs')} PDF</button><button class="btn sec" data-act="pwGo">${ms('refresh', 'xs')} Regenerează</button></div>` : `<div class="empty" style="padding-top:120px">${ms('auto_awesome')}<b>Programul apare aici</b><div style="margin-top:4px;font-size:13px">Alege timpul, transportul și interesele, apoi „Generează programul”.</div></div>`}</section>
    <div class="map" id="plmap" style="height:calc(100vh - 150px);position:sticky;top:84px"></div></div>`,
    after: () => { const map = mkMap('plmap', { zoom: 14, me: false }); if (!map) return; if (stops.length) { const pts = stops.map(s => [s.lat, s.lng]); L.polyline(pts, { color: '#111', weight: 4, dashArray: '1 9' }).addTo(map); stops.forEach((s, i) => L.marker([s.lat, s.lng], { icon: pinIcon('num', i + 1) }).addTo(map)); map.fitBounds(pts, { padding: [60, 60] }); } } };
});
function stopInfoW(s) { if (s.kind === 'event') { const e = A.allEvents().find(x => x.id === s.ref); return { title: s.title || e.title, img: e.img, tone: e.tone, emoji: e.emoji, href: '/events/' + e.id, lat: e.lat, lng: e.lng }; } if (s.kind === 'biz') { const b = A.allBiz().find(x => x.id === s.ref); return { title: s.title || b.name, img: b.img, href: '/businesses/' + b.id, lat: b.lat, lng: b.lng }; } const p = A.byId(A.PLACES, s.ref); return { title: s.title || p.name, img: p.img, tone: p.tone, emoji: '📍', href: '/places/' + p.id, lat: p.lat, lng: p.lng, guide: true }; }
ACT.pw = a => { const [k, v] = a.split(':'); const w = UI.plan; if (k === 'interests') { const i = w.interests.indexOf(v); i >= 0 ? w.interests.splice(i, 1) : w.interests.push(v); } else w[k] = v; render(); };
ACT.pwGo = () => { const w = UI.plan; w.loading = true; render(); setTimeout(() => { w.loading = false; w.result = Object.assign({}, A.GEN_ITIN); const i = S.newItins.findIndex(x => x.id === 'it3'); const it = Object.assign({}, A.GEN_ITIN, { ask: `„${w.time}, ${w.transport}, ${w.interests.join(' + ')}”` }); if (i >= 0) S.newItins[i] = it; else S.newItins.push(it); save(); render(); }, 1400); };

/* ---------- W11 Oferte ---------- */
route('/offers', () => {
  const cat = UI.tmp.oc || 'all'; let list = A.pubOffers(); if (cat !== 'all') list = list.filter(o => cat === 'points' ? o.pointsPrice : cat === 'local' ? (A.allBiz().find(b => b.id === o.biz) || {}).local : o.cat === cat);
  return { title: 'Oferte', body: `<h1>Oferte de la firmele din Arad</h1><div class="sub">Revendici în aplicație, arăți codul la casă. Unele se plătesc cu punctele din acțiunile comunitare.</div>
    <div class="row" style="margin:18px 0;padding:14px 18px;border-radius:16px;background:var(--yellow);gap:14px">${ms('local_cafe')}<div class="grow"><b>Doar în AradExperience: până la -20% la cafenelele din centru</b><div style="font-size:12.5px;opacity:.8">7 cafenele participante · valabil până pe 30 nov.</div></div><button class="btn sm" data-act="oc" data-arg="cafe">Vezi cafenelele</button></div>
    <div class="row" style="margin-bottom:16px;flex-wrap:wrap"><div class="chips">${[['all', 'Toate'], ['cafe', '☕ Cafenele'], ['rest', '🍽️ Restaurante'], ['local', '🧺 Făcut în Arad'], ['event', '🎉 Evenimente'], ['points', '⭐ Cu puncte']].map(([k, l]) => `<button class="chip ${cat === k ? 'on' : ''}" data-act="oc" data-arg="${k}">${l}</button>`).join('')}</div><span class="grow"></span><button class="chip" data-act="na">${ms('near_me', 'xs')} Lângă mine</button></div>
    ${S.role === 'local' ? `<div class="card pad row" style="gap:12px;margin-bottom:16px;background:var(--green-soft);border:none">${ms('stars')}<span>Ai <b>${A.pts(S.points)}</b>. Ofertele marcate „Cu puncte” le plătești direct de aici.</span></div>` : ''}
    <div class="grid4">${list.map(offerCardW).join('') || empty('sell', 'Nicio ofertă', 'Alege altă categorie.')}</div>` };
});
ACT.oc = a => { UI.tmp.oc = a; render(); };
ACT.claim = a => { const [id, mode] = a.split(':'); const o = A.allOffers().find(x => x.id === id); if (!S.user) { toast('Conectează-te ca să revendici oferta.'); go('/login'); return; } if (mode === 'pts') { if (S.points < o.pointsPrice) { toast('Nu ai destule puncte.'); return; } S.points -= o.pointsPrice; } S.claims.push({ code: A.genCode(`AX-O${id.replace('o', '')}`), offerId: id, at: A.TODAY, points: mode === 'pts' ? o.pointsPrice : 0 }); save(); ACT.offerCode(id); render(); };
ACT.offerCode = id => { const c = S.claims.find(x => x.offerId === id); const o = A.allOffers().find(x => x.id === id); const b = A.allBiz().find(x => x.id === o.biz); drawer(`<h2>Codul tău</h2><div class="sub">${esc(o.title)} · ${esc(b.name)}</div><div class="card pad" style="margin:16px 0;text-align:center">${qrW(c.code, 200).replace('style="width:200px"', 'style="width:200px;margin:0 auto"')}<code style="font-size:14px;margin-top:10px;display:inline-block">${c.code}</code>${c.points ? `<div><span class="badge pts" style="margin-top:8px">Plătită cu ${c.points} de puncte</span></div>` : ''}</div><div class="mut" style="font-size:13px;line-height:1.5">Arată codul la casă (pe telefon, din aplicație). Firma îl validează o singură dată. ${o.validUntil ? 'Valabil până ' + A.dayLabel(o.validUntil).toLowerCase() + '.' : ''}</div><a class="btn sec" style="margin-top:16px" href="#/account/offers">Ofertele mele</a>`); };

/* ---------- W12 Comunitate ---------- */
route('/community', () => {
  const f = UI.tmp.cf || 'up'; const acts = A.pubActions().filter(a => f === 'up' || f === 'all' || a.cat === f);
  return { title: 'Comunitate', body: `<h1>Comunitate</h1><div class="sub">Acțiuni organizate de Primăria Arad. Participi, un voluntar al Primăriei îți scanează codul, primești puncte pe care le folosești la firmele locale.</div>
    <div class="split" style="margin-top:18px"><div><div class="chips" style="margin-bottom:14px">${[['up', 'Urmează'], ['all', 'Toate'], ['Mediu', '🌳 Mediu'], ['Sănătate', '🩸 Sănătate'], ['Social', '🤝 Social']].map(([k, l]) => `<button class="chip ${f === k ? 'on' : ''}" data-act="cf" data-arg="${k}">${l}</button>`).join('')}</div>
      ${acts.map(a => { const reg = S.regs.find(r => r.action === a.id); const st = reg ? ((S.validations[reg.code] || {}).status || reg.status) : null; return `<div class="card pad row" style="gap:16px;margin-bottom:12px;align-items:flex-start"><div class="thumb" style="width:110px;height:78px;border-radius:12px;${imgStyle(a)}">${a.img ? '' : a.emoji}</div><div class="grow"><div class="row" style="gap:8px"><b style="font-size:15px">${esc(a.title)}</b><span class="badge pts">+${a.pts} puncte</span></div><div class="mut" style="font-size:13px;margin-top:3px">${A.dayLabel(a.date)} · ${a.time}–${a.end} · ${esc(a.place)}</div><div class="mut" style="font-size:13px;margin-top:3px">${a.taken + (reg ? 1 : 0)}/${a.spots} locuri · ${(a.going || []).join(', ')}${a.taken > (a.going || []).length ? ` și încă ${a.taken - a.going.length} merg` : ''}</div></div><div class="col" style="gap:6px;align-items:flex-end">${reg ? `<button class="btn sm ${st === 'CONFIRMED' ? 'green' : 'soft'}" data-act="myQrW" data-arg="${reg.code}">${st === 'CONFIRMED' ? ms('check_circle', 'xs') + ' Confirmat +' + a.pts : ms('qr_code_2', 'xs') + ' QR-ul meu'}</button>` : S.role === 'local' ? `<button class="btn sm" data-act="registerW" data-arg="${a.id}">Mă înscriu</button>` : `<button class="btn sm" data-act="toast" data-arg="Acțiunile comunitare sunt pentru localnici: conectează-te cu un cont de localnic.">Mă înscriu</button>`}<button class="btn sm sec" data-act="actDetail" data-arg="${a.id}">Detalii</button></div></div>`; }).join('')}</div>
    <aside class="col" style="gap:14px">${S.role === 'local' ? `<div class="ptscard"><div style="font-size:12.5px;opacity:.85">Punctele tale</div><div class="n">${S.points}</div><div class="row" style="justify-content:space-between;font-size:12.5px"><span>🔥 Activ 2 luni la rând</span><b>Locul 16</b></div></div>` : `<div class="card pad"><b>Cum funcționează</b><ol style="margin:8px 0 0;padding-left:18px;color:var(--mut);font-size:13.5px;line-height:1.6"><li>Te înscrii la o acțiune și primești un cod QR.</li><li>La fața locului, un voluntar al Primăriei îl scanează.</li><li>Primești punctele; le folosești la oferte „Cu puncte”.</li></ol><a class="btn sm" style="margin-top:12px" href="#/login">Conectează-te ca localnic</a></div>`}
      <div class="card pad"><div class="row" style="justify-content:space-between"><b>Clasament · noiembrie</b><a class="chip sm" href="#/community">Anul 2026</a></div>${A.BOARD.slice(0, 5).map((b, i) => `<div class="lrow"><span class="n">${i + 1}</span><span class="grow">${b[0]}</span><b>${b[1]}</b></div>`).join('')}<div class="lrow"><span class="n">16</span><span class="grow">Ana P. ${S.role === 'local' ? '<span class="badge pts" style="font-size:10.5px">tu</span>' : ''}</span><b>270</b></div><div class="mut" style="font-size:12px;margin-top:10px">Primii 50 sunt invitați la Gala Voluntarilor, 19 decembrie. Premii: abonament Teatrul Clasic, Filarmonica, cină pentru două persoane.</div></div>
      <div class="card pad"><b>Folosește punctele</b>${A.REWARDS.map(w => `<div class="kv">${ms(w.icon)}<span class="grow">${w.title}<div class="mut" style="font-size:12px">${w.biz}</div></span><span class="badge pts">${w.cost} p</span></div>`).join('')}</div></aside></div>` };
});
ACT.cf = a => { UI.tmp.cf = a; render(); };
ACT.registerW = id => { const code = A.genCode(`AX-${id.toUpperCase()}`); S.regs.push({ id: 'g' + Date.now(), action: id, who: S.user.name, code, at: 'vin., 6 nov.', status: 'PENDING' }); save(); ACT.myQrW(code); render(); };
ACT.myQrW = code => { const r = S.regs.find(x => x.code === code) || A.allRegs().find(x => x.code === code); const a = A.allActions().find(x => x.id === r.action); const st = (S.validations[code] || {}).status || r.status; drawer(`<h2>Codul tău</h2><div class="sub">${esc(a.title)} · ${A.dayLabel(a.date)} · ${a.time}–${a.end}</div><div class="card pad" style="margin:16px 0;text-align:center">${qrW(code, 200).replace('style="width:200px"', 'style="width:200px;margin:0 auto"')}<code style="font-size:14px;margin-top:10px;display:inline-block">${code}</code></div><div class="card pad" style="background:${st === 'CONFIRMED' ? 'var(--green-soft)' : 'var(--soft)'};border:none;font-size:13.5px">${st === 'CONFIRMED' ? `${ms('check_circle', 'xs')} Prezență confirmată · +${a.pts} puncte` : `${ms('info', 'xs')} Arată codul voluntarului Primăriei la începutul acțiunii (din aplicația de telefon). După scanare primești punctele.`}</div>`); };
ACT.actDetail = id => { const a = A.allActions().find(x => x.id === id); drawer(`<div class="hero" style="${imgStyle(a)};min-height:180px;border-radius:14px"><div><span class="badge pts">+${a.pts} puncte</span><h1 style="font-size:24px;margin-top:8px">${esc(a.title)}</h1></div></div><div class="kv" style="margin-top:12px">${ms('schedule')}<span>${A.dayLabel(a.date)} · ${a.time}–${a.end}</span></div><div class="kv">${ms('location_on')}<span>${esc(a.place)}</span></div><div class="kv">${ms('group')}<span>${a.taken}/${a.spots} locuri · ${a.dept}</span></div><p style="font-size:14px;color:var(--mut);line-height:1.55;margin-top:12px">${esc(a.desc)}</p><h3 style="margin:16px 0 8px">Cum primești punctele</h3>${['Te înscrii și primești un cod QR în Contul meu / aplicație.', 'Vii la acțiune; un voluntar al Primăriei îți scanează codul.', `Primești +${a.pts} puncte, de folosit la firmele partenere.`].map((t, i) => `<div class="gp"><span class="n">${i + 1}</span><p style="color:var(--ink)">${t}</p></div>`).join('')}${S.role === 'local' && !S.regs.find(r => r.action === id) ? `<button class="btn lg" style="width:100%;margin-top:16px" data-act="registerW" data-arg="${id}">Mă înscriu · +${a.pts} puncte</button>` : ''}`); };

/* ---------- W13 Chat ---------- */
function chatInitW() { if (!UI.chat) UI.chat = { msgs: [{ from: 'bot', text: 'Bună! Spune-mi ce ai chef să faci, când și cu cine.' }] }; return UI.chat; }
route('/chat', () => {
  const c = chatInitW();
  return { title: 'Chat', body: `<div class="split"><div class="card" style="display:flex;flex-direction:column;height:calc(100vh - 150px)"><div class="row" style="padding:14px 18px;border-bottom:1px solid var(--line)"><div class="grow"><b>Asistentul AradExperience</b><div class="mut" style="font-size:12.5px">Găsește evenimente și răspunde la întrebări despre ele. Nu face plăți.</div></div><button class="chip sm" data-act="chatNewW">${ms('edit_square', 'xs')} Chat nou</button></div>
      <div class="col" style="gap:10px;padding:18px;flex:1;overflow-y:auto" id="wchat">${c.msgs.map(m => `<div class="bubble ${m.from}">${esc(m.text)}</div>${m.chips ? `<div class="chips">${m.chips.map(ch => `<button class="chip sm" data-act="chatSendW" data-arg="${esc(ch)}">${esc(ch)}</button>`).join('')}</div>` : ''}${m.events ? `<div class="grid3" style="max-width:720px">${m.events.map(id => evCardW(A.allEvents().find(x => x.id === id), true)).join('')}</div>` : ''}${m.itin ? `<a class="card pad row" href="#/plan" style="gap:12px;max-width:420px;text-decoration:none">${ms('auto_awesome')}<div class="grow"><b>Itinerariu generat</b><div class="mut" style="font-size:12.5px">Deschide-l în Planificator sau în aplicație.</div></div>${ms('chevron_right')}</a>` : ''}`).join('')}${c.typing ? '<div class="bubble bot mut">…</div>' : ''}</div>
      <div class="row" style="padding:12px 18px;border-top:1px solid var(--line)"><div class="search grow">${ms('chat_bubble', 's')}<input placeholder="Mesaj…" data-bind="wchatIn" data-enter="chatSendInputW" value="${esc(UI.tmp.wchatIn || '')}"></div><button class="btn" style="width:46px;padding:0;border-radius:12px" data-act="chatSendInputW">${ms('arrow_upward', 's')}</button></div></div>
    <aside class="col" style="gap:14px"><div class="card pad"><b>Întrebări frecvente</b><div class="col" style="gap:8px;margin-top:10px;align-items:flex-start">${['Ce pot face cu copiii în weekend?', 'Ce concerte sunt săptămâna asta?', 'Cum ajung la Cetate?', 'Unde mănânc ciorbă de pește?', 'Ce e gratuit duminică?', 'Fă-mi un itinerariu de sâmbătă'].map(q => `<button class="chip sm" data-act="chatSendW" data-arg="${esc(q)}">${esc(q)}</button>`).join('')}</div></div><div class="card pad"><b>Cum funcționează</b><p class="sub" style="line-height:1.55">Răspunsurile folosesc doar evenimentele și locurile din aplicație (următoarele 14 zile). Dacă serviciul AI nu răspunde, primești un răspuns pregătit în avans, marcat „offline”.</p></div></aside></div>`,
    after: () => { const el = document.getElementById('wchat'); if (el) el.scrollTop = el.scrollHeight; } };
});
ACT.chatNewW = () => { UI.chat = null; render(); };
ACT.chatSendInputW = () => { const t = (UI.tmp.wchatIn || '').trim(); if (!t) return; UI.tmp.wchatIn = ''; ACT.chatSendW(t); };
ACT.chatSendW = text => { const c = chatInitW(); c.msgs.push({ from: 'me', text }); c.typing = true; render(); setTimeout(() => { c.typing = false; c.msgs.push(botReplyW(text)); render(); }, 800); };
function botReplyW(t) { const n = t.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  if (/itinerar|plan/.test(n)) { UI.plan = Object.assign(UI.plan || { time: 'half', day: '2026-11-07', transport: 'walk', interests: ['istorie'], text: '' }, { result: Object.assign({}, A.GEN_ITIN) }); return { from: 'bot', text: 'Ți-am făcut un plan pentru sâmbătă, pe jos, prin centrul istoric: Cetatea cu ghid audio, o cafea la Pasaj, Palatul Cultural și prânz pe Faleză.', itin: true }; }
  if (/copi/.test(n) && !/samb|dumin|weekend/.test(n)) return { from: 'bot', text: 'Pentru ce zi cauți?', chips: ['Sâmbătă, 7 nov.', 'Duminică, 8 nov.', 'Tot weekendul'] };
  if (/samb|weekend/.test(n)) return { from: 'bot', text: 'Sâmbătă aveți trei variante bune pentru copii. Teatrul de păpuși de la 11:00 e cel mai potrivit pentru cei mici (de la 3 ani); dacă vreți aer liber, plantarea de pe Faleză e gratuită și primiți și puncte. Seara, plimbarea ghidată la Cetate e gratuită, dar e mai lungă.', events: ['ev4', 'ev5', 'ev7'] };
  if (/dumin/.test(n)) return { from: 'bot', text: 'Duminică spectacolul de păpuși e epuizat. Rămân crosul din Pădurea Ceala și prânzul pe Faleză.', events: ['ev8', 'ev9'] };
  if (/concert/.test(n)) return { from: 'bot', text: 'Săptămâna aceasta sunt 3 concerte:', events: ['ev2', 'ev10', 'ev12'] };
  if (/cetat/.test(n)) return { from: 'bot', text: 'Cetatea e peste Mureș, la 1,2 km de centru: 20 de minute pe jos, peste Podul Traian. Se vizitează doar din exterior; ghidul audio are 6 puncte.', events: ['ev5'], chips: ['Deschide ghidul Cetății', 'Arată traseul pe hartă'] };
  if (/ghid/.test(n)) { setTimeout(() => go('/places/ca'), 300); return { from: 'bot', text: 'Deschid ghidul.' }; }
  if (/traseu|harta/.test(n)) { setTimeout(() => go('/map?to=pl:ca'), 300); return { from: 'bot', text: 'Deschid harta cu traseul.' }; }
  if (/ciorb|manan/.test(n)) return { from: 'bot', text: 'Ciorba de pește e specialitatea de la Bistro La Mureș, pe Faleză (★ 4,7). Duminică au și un prânz cu rezervare în aplicație.', events: ['ev9'] };
  if (/gratuit/.test(n)) return { from: 'bot', text: 'Gratuit duminică: crosul din Pădurea Ceala (înscriere în aplicație) și atelierele pentru copii din Piața Catedralei încep din 14 noiembrie.', events: ['ev8', 'ev20'] };
  return { from: 'bot', text: `Nu am găsit evenimente pentru „${t}” în următoarele 14 zile. Răspund doar din evenimentele și locurile din aplicație.`, chips: ['Ce e azi?', 'Concerte', 'Fă-mi un itinerariu de sâmbătă'] }; }

/* ---------- W14 Contul meu ---------- */
route('/account', () => accountPage('tickets'));
route('/account/:tab', ({ tab }) => accountPage(tab));
function accountPage(tab) {
  if (!S.user) return { title: 'Contul meu', body: `<div class="empty" style="padding-top:100px">${ms('person')}<b>Nu ești conectat</b><div style="margin:6px 0 14px;font-size:13px">Biletele, punctele și itinerariile tale apar aici.</div><a class="btn" href="#/login">Conectare</a></div>` };
  const menu = [['tickets', 'Biletele mele', 'confirmation_number'], ['saved', 'Salvate', 'bookmark'], ['points', 'Puncte & înscrieri', 'volunteer_activism'], ['offers', 'Ofertele mele', 'sell'], ['itineraries', 'Itinerariile mele', 'auto_awesome'], ['settings', 'Setări', 'settings']];
  let body = '';
  if (tab === 'tickets') { const up = S.tickets.filter(t => !t.past), past = S.tickets.filter(t => t.past); body = `<h2>Biletele mele</h2><div class="sub">Biletele cumpărate în aplicație. Pe cele de pe site-ul organizatorului le găsești în e-mail.</div><div class="tabs" style="margin-top:14px"><button class="on">Viitoare (${up.length})</button><button>Trecute (${past.length})</button></div>${up.map(t => { const e = A.allEvents().find(x => x.id === t.eventId); return `<div class="card pad row" style="gap:16px;margin-bottom:10px">${qrW(t.code, 64)}<div class="grow"><b>${esc(e.title)}</b><div class="mut" style="font-size:13px">${A.dayLabel(t.date)} · ${t.time} · ${esc(e.venue)}</div><div class="row" style="gap:8px;margin-top:6px"><code>${t.code}</code><span class="mut" style="font-size:12.5px">${t.lines.map(l => `${l[1]} ${l[0].toLowerCase()}`).join(' + ')} · ${t.total ? A.lei(t.total) : 'gratuit'}</span></div></div><div class="col" style="gap:6px;align-items:flex-end"><span class="pill p-ok"><i></i>Confirmat</span><div class="row" style="gap:6px"><button class="btn sm sec" data-act="showTicket" data-arg="${t.code}">Arată pe tot ecranul</button><button class="btn sm sec" data-act="cal">Calendar</button></div></div></div>`; }).join('') || empty('confirmation_number', 'Încă nu ai bilete viitoare', 'Caută evenimente și rezervă.')}`; }
  else if (tab === 'saved') { const l = A.allEvents().filter(e => S.saved.includes(e.id)); body = `<h2>Salvate</h2><div class="grid3" style="margin-top:14px">${l.map(e => evCardW(e)).join('') || empty('bookmark', 'Nimic salvat')}</div>`; }
  else if (tab === 'points') { body = `<h2>Puncte & înscrieri</h2><div class="split" style="margin-top:14px"><div>${S.regs.length ? S.regs.map(r => { const a = A.allActions().find(x => x.id === r.action); const st = (S.validations[r.code] || {}).status || r.status; return `<div class="card pad row" style="gap:16px;margin-bottom:10px">${qrW(r.code, 64)}<div class="grow"><b>${esc(a.title)}</b><div class="mut" style="font-size:13px">${A.dayLabel(a.date)} · ${a.time} · +${a.pts} puncte</div><code style="margin-top:6px;display:inline-block">${r.code}</code></div>${pill(st)}<button class="btn sm sec" data-act="myQrW" data-arg="${r.code}">QR</button></div>`; }).join('') : empty('volunteer_activism', 'Nicio înscriere', 'Înscrie-te la o acțiune din Comunitate.')}<h3 style="margin:18px 0 8px">Istoric puncte</h3><div class="card" style="padding:4px 16px">${[['+50', 'Plantare pe Faleză', '10 oct.'], ['−30', 'Cafea -20% (Cafeneaua din Pasaj)', '2 nov.'], ['+40', 'Curățenie în Pădurea Ceala', '25 oct.']].map(h => `<div class="kv"><b style="width:44px;color:${h[0][0] === '+' ? 'var(--green)' : 'var(--bad)'}">${h[0]}</b><span class="grow">${h[1]}</span><span class="mut" style="font-size:12.5px">${h[2]}</span></div>`).join('')}</div></div><aside><div class="ptscard"><div style="font-size:12.5px;opacity:.85">Punctele tale</div><div class="n">${S.points}</div><div style="font-size:12.5px;opacity:.85">Nivel Voluntar · încă ${Math.max(0, 500 - S.points)} până la Ambasador · Locul 16</div></div></aside></div>`; }
  else if (tab === 'offers') { body = `<h2>Ofertele mele</h2>${S.claims.length ? S.claims.map(c => { const o = A.allOffers().find(x => x.id === c.offerId); const b = A.allBiz().find(x => x.id === o.biz); return `<div class="card pad row" style="gap:16px;margin:10px 0">${qrW(c.code, 64)}<div class="grow"><b>${esc(c.reward || o.title)}</b><div class="mut" style="font-size:13px">${esc(b.name)}${c.points ? ` · plătită cu ${c.points} p` : ''}</div><code style="margin-top:6px;display:inline-block">${c.code}</code></div>${pill(c.used ? 'USED' : 'ISSUED')}<button class="btn sm sec" data-act="offerCode" data-arg="${c.offerId}">Cod</button></div>`; }).join('') : empty('sell', 'Nicio ofertă revendicată', 'Vezi ofertele firmelor partenere.')}`; }
  else if (tab === 'itineraries') { const l = A.ITINS.concat(S.newItins); body = `<h2>Itinerariile mele</h2><div class="grid2" style="margin-top:14px">${l.map(it => { const c = stopInfoW({ kind: it.cover.startsWith('ev') ? 'event' : 'place', ref: it.cover }); return `<a class="evc" href="#/plan"><div class="img" style="${c.img ? `background-image:url('${c.img}')` : `background:${c.tone}`};height:110px"></div><div class="body"><b>${esc(it.title)}</b><span>${it.when} · ${it.stops.length} opriri · ${(S.itinDone[it.id] || it.done || []).length} bifate</span></div></a>`; }).join('')}</div>`; }
  else body = `<h2>Setări</h2><div class="card" style="padding:4px 16px;margin-top:14px"><div class="kv">${ms('person')}<span class="grow">${esc(S.user.name)} · ${esc(S.user.email)}</span><span class="badge">${S.role === 'local' ? 'Localnic' : 'Vizitator'}</span></div><div class="kv">${ms('language')}<span class="grow">Limba</span><span class="mut">Română</span></div><div class="kv">${ms('notifications')}<span class="grow">Mementouri cu o zi înainte</span><span class="badge ok">pornit</span></div><div class="kv">${ms('install_mobile')}<span class="grow">Instalează aplicația pe telefon (PWA)</span><button class="btn sm sec" data-act="na">Cum</button></div><div class="kv">${ms('logout')}<button class="grow" style="text-align:left;color:var(--bad)" data-act="logout">Deconectare</button></div></div>`;
  return { title: 'Contul meu', body: `<div class="split l"><aside><div class="card pad row" style="gap:12px;margin-bottom:12px">${avatarW(S.user.name, true)}<div><b>${esc(S.user.name)}</b><div class="mut" style="font-size:12px">${esc(S.user.email)}</div></div></div><div class="acct-menu">${menu.map(([k, l, ic]) => `<a href="#/account/${k}" class="${tab === k ? 'on' : ''}">${ms(ic, 's')}${l}</a>`).join('')}</div></aside><div>${body}</div></div>` };
}

/* ---------- W15 Pagina firmei ---------- */
route('/businesses/:id', ({ id }) => {
  const b = A.allBiz().find(x => x.id === id); if (!b) return { body: empty('error', 'Firmă inexistentă') }; const offers = A.pubOffers().filter(o => o.biz === id); const evs = A.pubEvents().filter(e => e.bizId === id && !e.past); const ann = A.allAnn().filter(a => a.biz === id && !a.expired); const rv = A.BIZ_REVIEWS[id] || [];
  return { title: b.name, body: `<div class="card pad row" style="gap:18px;align-items:flex-start"><div class="thumb" style="width:84px;height:84px;border-radius:16px;background-image:url('${b.img}')"></div><div class="grow"><div class="row" style="gap:8px"><h1 style="font-size:28px">${esc(b.name)}</h1>${b.verified ? `<span class="badge ok">${ms('verified', 'xs')} verificat</span>` : '<span class="badge warn">în verificare</span>'}${b.local ? '<span class="badge local">Făcut în Arad</span>' : ''}</div><div class="sub">${esc(b.cat)} · ${esc(b.addr)} · ★ ${b.rating} (${b.reviews} păreri) · ${esc(b.hours.split(' · ')[0])}</div><div class="chips" style="margin-top:10px">${b.tags.map(t => `<span class="badge">${esc(t)}</span>`).join('')}</div></div><div class="row" style="gap:8px"><a class="btn sec" href="#/map?to=bz:${id}">${ms('directions', 'xs')} Indicații</a><button class="btn sec" data-act="toast" data-arg="${b.phone}">${ms('call', 'xs')} ${b.phone.slice(0, 4)}…</button><button class="btn" data-act="toast" data-arg="Urmărești ${b.name}.">${ms('bookmark_border', 'xs')} Urmărește</button></div></div>
    <div class="split" style="margin-top:18px"><div>
      ${offers.length ? `<h2>Oferte active</h2><div class="grid3" style="margin:12px 0 24px">${offers.map(offerCardW).join('')}</div>` : ''}
      ${evs.length ? `<h2>Evenimente</h2>${evs.map(e => `<a class="card pad row" href="#/events/${e.id}" style="gap:14px;margin-top:10px;text-decoration:none">${thumbW(e)}<div class="grow"><b>${esc(e.title)}</b><div class="mut" style="font-size:13px">${A.whenLabel(e)} · ${A.priceLabel(e)} ${A.isHot(e) ? `· 🔥 ${e.participants} participă` : ''}</div></div><span class="btn sm sec">${e.ticket === 'IN_APP' ? 'Bilete' : 'Particip'}</span></a>`).join('')}` : ''}
      ${ann.length ? `<h2 style="margin-top:24px">Anunțuri</h2>${ann.map(a => `<div class="card pad" style="margin-top:10px"><b>${esc(a.title)}</b><div class="mut" style="font-size:13.5px;margin-top:2px">${esc(a.text)} <span style="font-size:12px">· ${a.at}</span></div></div>`).join('')}` : ''}
      <h2 style="margin-top:24px">Păreri</h2>${rv.map(r => `<div class="card pad" style="margin-top:10px"><div class="row" style="justify-content:space-between"><b style="font-size:13.5px">${esc(r.who)}</b><span class="stars" style="font-size:12px">${stars(r.stars)}</span></div><div class="mut" style="font-size:13.5px;margin-top:4px">„${esc(r.text)}” <span style="font-size:12px">· ${r.at}</span></div></div>`).join('') || '<div class="sub">Încă nicio părere.</div>'}
    </div><aside class="col" style="gap:14px"><div class="card" style="overflow:hidden"><div id="bmap" style="height:220px"></div></div><div class="card pad"><b>Despre</b><p class="sub" style="line-height:1.55">${esc(b.tagline)}</p></div><div class="card pad"><b>Program</b><div class="kv" style="margin-top:4px">${ms('schedule')}<span>${esc(b.hours)}</span></div><div class="kv">${ms('location_on')}<span>${esc(b.addr)}, Arad</span></div><div class="kv">${ms('call')}<span>${b.phone}</span></div></div></aside></div>`,
    after: () => { const map = mkMap('bmap', { center: [b.lat, b.lng], zoom: 15, zoomControl: false }); if (map) L.marker([b.lat, b.lng], { icon: pinIcon('offer') }).addTo(map); } };
});

/* ---------- W0 Login / conturi ---------- */
route('/login', () => {
  const tab = UI.tmp.loginTab || 'personal'; const reg = UI.tmp.regMode;
  const personal = `${reg ? `<div class="f"><label>Nume</label><input class="in" placeholder="Prenume și nume"></div>` : ''}<div class="f"><label>Adresa de e-mail</label><input class="in" type="email" placeholder="nume@exemplu.ro" data-bind="lemail" value="${esc(UI.tmp.lemail || '')}"></div><div class="f"><label>Parola</label><input class="in" type="password" placeholder="minimum 8 caractere" data-bind="lpass" value="${esc(UI.tmp.lpass || '')}"></div>${reg ? `<div class="f"><label>Folosești aplicația ca</label><div class="fseg"><button class="${(UI.tmp.regRole || 'visitor') === 'visitor' ? 'on' : ''}" data-act="regRole" data-arg="visitor">Vizitator</button><button class="${UI.tmp.regRole === 'local' ? 'on' : ''}" data-act="regRole" data-arg="local">Localnic</button></div></div>` : ''}${UI.tmp.lerr ? `<div class="lnote" style="color:var(--bad);background:var(--badbg)">${esc(UI.tmp.lerr)}</div>` : ''}<button class="btn lg" style="width:100%" data-act="wlogin">${reg ? 'Creează contul' : 'Intră în cont'}</button><button class="chip sm" style="align-self:center;border:none" data-act="regMode">${reg ? 'Ai deja cont? Conectează-te' : 'Nu ai cont? Creează unul'}</button><div class="lnote">${ms('bolt', 's')}<span>Conturi demo: ${['visitor@demo.ro', 'local@demo.ro'].map(e => `<button class="chip sm" data-act="demoAcc" data-arg="${e}">${e}</button>`).join(' ')} · parola <code>demo1234</code></span></div><div class="lnote">${ms('storefront', 's')}<span>Ai o firmă în Arad? <button class="chip sm" data-act="firmReg">Înregistrează-ți firma</button> Contul devine activ după verificarea Primăriei.</span></div>`;
  const panels = `<button class="acct" data-act="switchRole" data-arg="city"><div class="top"><span class="ic">${ms('account_balance')}</span><div><h3>Primăria Arad</h3><div class="d">Administrator complet: agendă, comunitate, voluntari, firme, obiective</div></div></div></button>
    <div class="acct"><div class="top"><span class="ic" style="background:var(--acc)">${ms('storefront')}</span><div><h3>Firmă parteneră</h3><div class="d">Contul e creat de Primărie sau înregistrat și verificat</div></div></div><div class="row"><select class="in grow" data-bind="loginFirm">${A.allBiz().map(b => `<option value="${b.id}" ${b.id === S.firmId ? 'selected' : ''}>${esc(b.name)}${b.verified ? '' : ' (neverificată)'}</option>`).join('')}</select><button class="btn" data-act="firmEnter">Intră</button></div></div>
    <button class="acct" data-act="switchRole" data-arg="admin"><div class="top"><span class="ic" style="background:#2A2A30">${ms('shield_person')}</span><div><h3>Administrator platformă</h3><div class="d">admin@demo.ro · moderare conținut, utilizatori, setări</div></div></div></button>
    <div class="lnote">${ms('badge', 's')}<span>Voluntarii nu au acces aici: ei se conectează în aplicația de telefon, cu codul primit prin SMS după ce Primăria le creează contul.</span></div>`;
  return { title: 'Conectare', body: `<div class="login"><div class="lside"><a class="brand" href="#/" style="color:#fff"><span class="logo" style="width:30px;height:30px;border-radius:9px;background:var(--acc);display:inline-flex;align-items:center;justify-content:center">${ms('location_city', 's')}</span>AradExperience</a><div><h1>Orașul tău, într-un singur loc.</h1><p>Evenimente, obiective cu ghid, oferte și acțiuni comunitare, pentru arădeni și vizitatori. Primăria și firmele partenere publică direct în aplicație.</p></div><div class="lstats"><div><b>${A.pubEvents().length}</b><span>evenimente</span></div><div><b>${A.PLACES.length}</b><span>obiective cu ghid</span></div><div><b>${A.allBiz().filter(b => b.verified).length}</b><span>firme partenere</span></div></div></div>
    <div class="lmain"><div class="lbox"><div class="seg" style="align-self:flex-start"><button class="${tab === 'personal' ? 'on' : ''}" data-act="loginTab" data-arg="personal">Cont personal</button><button class="${tab === 'panels' ? 'on' : ''}" data-act="loginTab" data-arg="panels">Panouri (Primărie · Firmă · Admin)</button></div><h2>${tab === 'personal' ? (reg ? 'Creează un cont' : 'Conectează-te') : 'Alege contul'}</h2><p>${tab === 'personal' ? 'Bilete, puncte și itinerarii sincronizate cu aplicația de telefon.' : 'Conturi demonstrative. Totul rămâne în acest browser.'}</p>${tab === 'personal' ? personal : panels}<a href="#/" class="chip sm" style="align-self:center;border:none;text-decoration:none">${ms('arrow_back', 'xs')} Înapoi la site</a></div></div></div>` };
});
ACT.loginTab = a => { UI.tmp.loginTab = a; render(); }; ACT.regMode = () => { UI.tmp.regMode = !UI.tmp.regMode; render(); }; ACT.regRole = a => { UI.tmp.regRole = a; render(); }; ACT.demoAcc = e => { UI.tmp.lemail = e; UI.tmp.lpass = 'demo1234'; UI.tmp.lerr = ''; render(); };
ACT.wlogin = () => { const email = (UI.tmp.lemail || '').trim().toLowerCase(); const pass = UI.tmp.lpass || ''; if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { UI.tmp.lerr = 'Introdu o adresă de e-mail validă.'; render(); return; } if (pass.length < 8) { UI.tmp.lerr = 'Parola are minimum 8 caractere (demo1234).'; render(); return; } const map = { 'visitor@demo.ro': ['visitor', 'John S.'], 'local@demo.ro': ['local', 'Ana P.'], 'firma@demo.ro': ['business'], 'primaria@demo.ro': ['city'], 'admin@demo.ro': ['admin'] }; const m = map[email] || [UI.tmp.regMode ? (UI.tmp.regRole || 'visitor') : 'visitor', email.split('@')[0]]; UI.tmp.lerr = ''; if (['business', 'city', 'admin'].includes(m[0])) { S.adminRole = m[0]; save(); go(m[0] === 'business' ? '/business' : m[0] === 'admin' ? '/admin' : '/city'); return; } S.role = m[0]; S.user = { name: m[1], email }; save(); toast(`Bun venit, ${m[1]}!`, 'check_circle'); go('/'); };
ACT.firmEnter = () => { S.firmId = UI.tmp.loginFirm || S.firmId || 'r2'; S.adminRole = 'business'; save(); go('/business'); };
ACT.firmReg = () => { UI.form = {}; drawer(`<h2>Înregistrează-ți firma</h2><div class="sub">Contul e neverificat până îl aprobă Primăria. Până atunci poți pregăti oferte și evenimente în ciornă.</div><div class="col" style="gap:14px;margin-top:16px">${field('Numele firmei', 'name', 'text', { ph: 'Ex.: Ceainăria din Parc' })}<div class="two">${field('Tip', 'cat', 'select', { options: [['Cafenea', 'Cafenea'], ['Restaurant', 'Restaurant'], ['Brutărie · producător', 'Producător local'], ['Cramă', 'Cramă'], ['Magazin', 'Magazin'], ['Altceva', 'Altceva']] })}${field('Zonă', 'zone', 'select', { options: [['Centru', 'Centru'], ['Faleză', 'Faleză'], ['Subcetate', 'Subcetate'], ['Aradul Nou', 'Aradul Nou'], ['Județ', 'Județ'], ['Micălaca', 'Micălaca']] })}</div>${field('Adresa', 'addr', 'text', { ph: 'Str. …, nr. …' })}${field('Persoana de contact', 'contact', 'text', { ph: 'Prenume și nume' })}<div class="two">${field('E-mail', 'email', 'email', { ph: 'contact@firma.ro' })}${field('Telefon', 'phone', 'text', { ph: '0257 xxx xxx' })}</div>${field('Produs „Făcut în Arad”', 'local', 'toggle', { hint: 'Apare cu insigna „Făcut în Arad” în aplicație.' })}<button class="btn lg" data-act="firmRegGo">${ms('add_business', 's')} Trimite spre verificare</button></div>`); };
ACT.firmRegGo = () => { const f = UI.form; if (!f.name) { toast('Scrie numele firmei.'); return; } const id = 'nf' + Date.now(); S.created.firms.push({ id, name: f.name, cat: f.cat || 'Cafenea', zone: f.zone || 'Centru', addr: f.addr || 'Arad', lat: 46.175 + Math.random() * .006, lng: 21.312 + Math.random() * .008, rating: 0, reviews: 0, verified: false, local: !!f.local, color: '#5B5F6B', img: 'shared/img/loc-gradina-restaurant.jpg', phone: f.phone || '', email: f.email || '', contact: f.contact || '', hours: '—', tagline: 'Cont înregistrat azi, în așteptarea verificării.', tags: [], dist: .5, since: 'azi, ' + A.NOW, views: 0, codesUsed: 0, pointsPay: 0, pointsIn: 0 }); S.firmId = id; S.adminRole = 'business'; save(); closeDrawer(); toast('Cont creat. Primăria primește cererea de verificare.', 'check_circle'); go('/business'); };
